        content = file.read()

    tree = ast.parse(content)

    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == 'SETTINGS':
                    if isinstance(node.value, ast.Dict):
                        settings_dict = {}
                        for key_node, value_node in zip(node.value.keys, node.value.values):
                            if isinstance(key_node, ast.Str):
                                key = key_node.s
                            elif isinstance(key_node, ast.NameConstant):
                                key = key_node.value
                            else:
                                continue

                            if isinstance(value_node, ast.Num):
                                settings_dict[key] = int(value_node.n)
                            elif isinstance(value_node, ast.Str):
                                settings_dict[key] = value_node.s
                            elif isinstance(value_node, ast.List):
                                list_values = []
                                for element in value_node.elts:
                                    if isinstance(element, ast.Str):
                                        list_values.append(element.s)
                                    elif isinstance(element, ast.Num):
                                        list_values.append(int(element.n))
                                settings_dict[key] = list_values
                        return json.dumps(settings_dict)
    return None

