import json
import sys

def parse_value(value_str):
    value_str = value_str.strip()
    if value_str.startswith('[') and value_str.endswith(']'):
        # Handle list
        items = []
        current = []
        i = 1
        while i < len(value_str) - 1:
            if value_str[i] == '[':
                current.append('[')
            elif value_str[i] == ']':
                current.append(']')
            elif value_str[i] == ',':
                items.append(''.join(current))
                current = []
            else:
                current.append(value_str[i])
            i += 1
        items.append(''.join(current))
        return [parse_value(item) for item in items]
    elif value_str.startswith('{') and value_str.endswith('}'):
        # Handle dict
        items = {}
        current_key = []
        current_value = []
        i = 1
        while i < len(value_str) - 1:
            if value_str[i] == '{':
                current_value.append('{')
            elif value_str[i] == '}':
                current_value.append('}')
            elif value_str[i] == ',':
                if current_key:
                    key = ''.join(current_key)
                    value = parse_value(''.join(current_value))
                    items[key] = value
                    current_key = []
                    current_value = []
            elif value_str[i] == ':' and not current_key:
                current_value = []
            elif value_str[i] == '"':
                # Handle string keys
                j = i + 1
                while j < len(value_str) and value_str[j] != '"':
                    current_key.append(value_str[j])
                    j += 1
                i = j
            else:
                current_value.append(value_str[i])
            i += 1
        if current_key:
            key = ''.join(current_key)
            value = parse_value(''.join(current_value))
            items[key] = value
        return items
    elif value_str == 'None':
        return None
    elif value_str == 'True':
        return True
    elif value_str == 'False':
        return False
    elif value_str.startswith('"') and value_str.endswith('"'):
        return value_str[1:-1]
    elif value_str.lstrip('-').isdigit():
        return int(value_str)
    else:
        return value_str

