import sys
import json
import re
from typing import Dict, Any, Union

def parse_value(value_str: str, key_dict: Dict[str, Any]) -> Any:
    try:
        # Try to evaluate the value as a Python expression
        return eval(value_str, {'__builtins__': None}, key_dict)
    except NameError as e:
        if "name '\" + str(e.args[0]) + \"" in str(e):
            raise ValueError(f"error: undefined key {e.args[0]}") from e
        raise

def process_file(path: str) -> None:
    key_dict = {}
    lines = []
    with open(path, 'r') as f:
        lines = f.readlines()

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line format: {line}")

        key_part, value_part = line.split('=', 1)
        key = key_part.strip()
        value = value_part.strip()

        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
            raise ValueError(f"Invalid key format: {key}")

        try:
            value_expr = parse_value(value, key_dict)
        except ValueError as e:
            print(e, file=sys.stderr)
            sys.exit(1)

        key_dict[key] = value_expr

    print(json.dumps(key_dict))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python extract.py <path>", file=sys.stderr)
        sys.exit(1)

    process_file(sys.argv[1])

import sys
import json
import re

def parse_value(value_str):
    # Check if value is an integer
    if re.fullmatch(r'-?\d+', value_str):
        return int(value_str)
    # Check if value is a quoted string
    elif value_str.startswith('"') and value_str.endswith('"') and not re.search(r'\"', value_str):
        return value_str[1:-1]
    # Check if value is a key name
    elif re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', value_str):
        return value_str
    else:
        raise ValueError(f"Invalid value format: {value_str}")

def process_file(path):
    key_to_value = {}
    seen_keys = set()

    with open(path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line:
                continue
            if '=' not in line:
                print(f"error: invalid line format: {line}", file=sys.stderr)
                sys.exit(1)

            key_part, value_part = line.split('=', 1)
            key = key_part.strip()
            value = value_part.strip()

            if key not in key_to_value:
                seen_keys.add(key)

            try:
                if value in key_to_value:
                    key_to_value[key] = key_to_value[value]
                else:
                    key_to_value[key] = parse_value(value)
            except ValueError as e:
                print(f"error: invalid value format: {value}", file=sys.stderr)
                sys.exit(1)

    for key in seen_keys:
        if key not in key_to_value:
            print(f"error: undefined key {key}", file=sys.stderr)
            sys.exit(1)

    print(json.dumps(key_to_value))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python extract.py <path>", file=sys.stderr)
        sys.exit(1)

    process_file(sys.argv[1])

