import json

def parse_line(line):
    line = line.strip()
    if not line:
        return None
    try:
        key, value = line.split('=', 1)
        key = key.strip()
        if not key:
            return None
        if not key[0].isalpha() or not key[0].isalnum() or key[0] == '_':
            return None
        for c in key[1:]:
            if not (c.isalnum() or c == '_'):
                return None
        if value.startswith('"') and value.endswith('"'):
            return key, value[1:-1]
        try:
            value = int(value)
            return key, value
        except ValueError:
            return None
    except ValueError:
        return None

def main():
    path = sys.argv[1]
    with open(path, 'r') as file:
        lines = file.readlines()
    result = {}
    for line in lines:
        parsed = parse_line(line)
        if parsed:
            key, value = parsed
            result[key] = value
    print(json.dumps(result))

if __name__ == "__main__":
    main()

