import sys
import json
import re

def parse_expression(expr):
    def evaluate(node):
        if isinstance(node, str):
            return globals().get(node, 0)
        elif isinstance(node, int):
            return node
        elif isinstance(node, list):
            op, left, right = node
            left_val = evaluate(left)
            right_val = evaluate(right)
            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '//':
                return left_val // right_val
            elif op == '%':
                return left_val % right_val
            elif op == '**':
                return left_val ** right_val
            else:
                raise ValueError(f"Unknown operator: {op}")
        elif node == '-':
            return -evaluate(node[0])
        elif node == '+':
            return evaluate(node[0])
        else:
            raise ValueError(f"Unknown node type: {node}")

    tokens = re.findall(r'(\d+|[A-Za-z_][A-Za-z0-9_]*|[-+*/%^()])', expr)
    tokens = [t for t in tokens if t not in (' ', '')]

    def parse():
        nonlocal tokens
        if not tokens:
            return None
        token = tokens.pop(0)
        if token.isdigit():
            return int(token)
        elif token in ('+', '-'):
            return token
        elif token == '(':
            left = parse()
            while tokens and tokens[0] in ('+', '-', '*', '/', '%', '**'):
                op = tokens.pop(0)
                right = parse()
                tokens.pop(0)  # Remove ')'
                left = (op, left, right)
            return left
        elif token in ('+', '-', '*', '/', '%', '**'):
            left = parse()
            op = token
            right = parse()
            return (op, left, right)
        else:
            return token

    return evaluate(parse())

def main():
    path = sys.argv[1]
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    variables = {}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if '=' not in line:
            continue
        key, expr = line.split('=', 1)
        key = key.strip()
        expr = expr.strip()
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
            continue
        value = parse_expression(expr)
        variables[key] = value

    print(json.dumps(variables))

if __name__ == '__main__':
    main()
